package com.spawnershop.api; import com.spawnershop.config.ShopItem; import org.bukkit.entity.Player; import org.bukkit.event.*; import java.math.BigDecimal;
public final class SpawnerBuyEvent extends Event implements Cancellable { private static final HandlerList HANDLERS=new HandlerList(); private final Player player; private final ShopItem item; private final int amount; private final BigDecimal value; private boolean cancelled; public SpawnerBuyEvent(Player p,ShopItem i,int a,BigDecimal v){player=p;item=i;amount=a;value=v;} public Player getPlayer(){return player;} public ShopItem getItem(){return item;} public int getAmount(){return amount;} public BigDecimal getValue(){return value;} public boolean isCancelled(){return cancelled;} public void setCancelled(boolean c){cancelled=c;} public HandlerList getHandlers(){return HANDLERS;} public static HandlerList getHandlerList(){return HANDLERS;} }
